    description: '鄱阳湖位于江西省北部，是中国第一大淡水湖，面积约 3960 平方公里（汛期可达 4000+）。古称"彭蠡""彭泽"，隋唐后始称鄱阳。是长江流域最大的调蓄湖泊，每年冬季成千上万只候鸟（白鹤、东方白鹳）来此越冬，"鄱阳湖观鸟"是世界级生态景观。京九铁路、赣江、信江、修水在此汇入长江。',
