    description: '青海湖位于青海省东北部，是世界上海拔最高的咸水湖之一（3196 米），中国最大的咸水湖，面积约 4546 平方公里。古称"西海""鲜水海""卑禾羌海"，北魏始称"青海"。吐谷浑、吐蕃、蒙古等游牧民族在此活动；丝绸之路"唐蕃古道"经湖畔；日月山、倒淌河诉说着文成公主入藏的故事。盛产湟鱼，湖中鸟岛是候鸟天堂。',
