    description: '巴尔喀什湖位于哈萨克斯坦东部，面积约 1.6 万平方公里，世界第十三大湖。奇特之处在于湖西部是淡水、东部是盐水——因为伊犁河从西岸注入（占总水量 75%），稀释了西半部，而东半部几乎无淡水注入、强烈蒸发形成盐湖。中亚丝绸之路沿湖行进，张骞通西域、玄奘西行均经过此湖。',
