    description: '拉多加湖位于俄罗斯西北部，是欧洲最大的湖泊，面积约 1.77 万平方公里。古称"涅瓦湖"，是 1240 年亚历山大·涅夫斯基在冰湖战役中击败瑞典的战场。彼得大帝在湖边建圣彼得堡（1703 年），列宁在湖畔展开革命活动（十月革命指挥部在拉兹利夫车站湖畔）。湖中岛屿约 660 个。',
