    description: '伏尔加河长约 3690 公里，是欧洲最长河流，俄罗斯的母亲河。发源于俄罗斯瓦尔代丘陵，注入里海。流域居住着俄罗斯近一半的人口，沿岸有莫斯科（支流）、下诺夫哥罗德、喀山、伏尔加格勒（原斯大林格勒）、阿斯特拉罕等城市。苏联歌曲《莫斯科郊外的晚上》《喀秋莎》《伏尔加船夫曲》都源于此。',
